func serviceConditionalChapter(t testing.TB) string {
	t.Helper()
	chapter := servicesRulesChapter(t)
	for _, rule := range serviceConditionalRules {
		if !strings.Contains(chapter, rule.quote) {
			t.Fatalf("chapter 5 no longer says %q", rule.quote)
		}
	}
	return chapter
}
func TestServiceConditionalKeysQuoted(t *testing.T) { serviceConditionalChapter(t) }

func FuzzServiceConditionalKeys(f *testing.F) {
	startShortBudget(f)
	chapter := serviceConditionalChapter(f)
	for _, rule := range serviceConditionalRules {
		f.Add([]byte(rule.key))
		f.Add([]byte(rule.key + "\x00\x03"))
	}
	w := NewWorkspace(f)
	f.Fuzz(func(t *testing.T, data []byte) {
		selected := 0
		if len(data) > 0 {
			selected = int(data[0]) % len(serviceConditionalRules)
		}
		parts := strings.SplitN(string(data), "\x00", 2)
		for i, rule := range serviceConditionalRules {
			if parts[0] == rule.key {
				selected = i
				break
			}
		}
		rule := serviceConditionalRules[selected]
		var variant byte
		if len(parts) > 1 && len(parts[1]) > 0 {
			variant = parts[1][0]
		}
		mutate := func(s string) string {
			if variant&1 != 0 {
				s = "// retained trivia\r\n" + strings.ReplaceAll(s, ";", ";\r\n")
			}
			if variant&2 != 0 {
				s = strings.ReplaceAll(s, "\"", "'")
			}
			return s
		}
		compile := func(source string) map[int32]int {
			result, err := w.Compile(t.Context(), Project{Files: map[string]string{"main.vibe": mutate(source), "package.json": servicesPackage}})
			if err != nil {
				t.Fatal(err)
			}
			defer result.Remove()
			codes := map[int32]int{}
			for _, d := range result.Diagnostics {
				if d.Category() == diagnostics.CategoryError {
					codes[d.Code()]++
				}
			}
			return codes
		}
		if got := compile(rule.good); len(got) != 0 {
			Gap(t, "FuzzServiceConditionalKeys", "control:"+rule.key, "chapter 5: %s; ordinary control reports %v", rule.quote, got)
			return
		}
		expected := servicesRuleDiagnostic(chapter, rule.quote)
		got := compile(rule.bad)
		if len(got) != 2 || got[expected] != 1 || got[2322] != 1 {
			Gap(t, "FuzzServiceConditionalKeys", "diagnostic:"+rule.key, "chapter 5: %s; want EK%04d and unrelated TS2322 once, got %v\n%s", rule.quote, expected, got, rule.bad)
			return
		}
		ExpectPending(t, "FuzzServiceConditionalKeys", "control:"+rule.key)
		ExpectPending(t, "FuzzServiceConditionalKeys", "diagnostic:"+rule.key)
		ExpectPending(t, "FuzzServiceConditionalKeys", specCorpusKey(t))
	})
}
